   z=row[c];row=[(x-z*y)%prime for x,y in zip(row,p)]
 if any(row):
  c=next(i for i,x in enumerate(row) if x);z=pow(row[c],-1,prime);row=[x*z%prime for x in row];pivs[c]=row
  return True
 return False
